mapper.select:
SELECT p.product_id, p.product_sn, p.product_name, p.product_stock, p.category_id, p.pic_url, ps.sku_id, ps.sku_data, ps.sku_stock, p.shop_id, p.product_price, ps.sku_price FROM product p LEFT JOIN product_sku ps ON ps.product_id = p.product_id AND ps.is_enabled = 1 WHERE p.is_delete = 0 AND p.product_status = 1 AND p.shop_id = #{shopId}
AND (p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.product_sn LIKE CONCAT('%', #{keyword}, '%'))
AND p.category_id IN
#{catId}
AND p.product_type IN
#{type}
AND p.product_type NOT IN
#{type}
AND (p.sale_mode IS NULL OR p.sale_mode = 0)
AND (p.delivery_mode = 0 OR p.delivery_mode = 1)
ORDER BY p.add_time DESC

SELECT p.product_id, p.product_sn, p.product_name, p.category_id, p.pic_url, p.product_type, ps.sku_id, ps.sku_data, p.shop_id, p.product_price, ps.sku_price FROM product p LEFT JOIN product_sku ps ON ps.product_id = p.product_id AND ps.is_enabled = 1 WHERE p.is_delete = 0 AND p.product_status = 1
AND p.product_id = #{productId}
AND ps.sku_id = #{skuId}
GROUP BY ps.sku_id
